import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/app/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        timestamp REAL
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, password_hash, role, api_key) VALUES ('admin', 'admin@corp.internal', 'pbkdf2:sha256:260000$salt$hash', 'admin', 'ak_prod_7f3a9b2c')")
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_session_token(token):
    """Verify HMAC-based session token: username.timestamp.signature"""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None
        username, ts, sig = parts
        if time.time() - float(ts) > 3600:
            return None
        expected = hmac.new(SECRET_KEY.encode(), f"{username}.{ts}".encode(), hashlib.sha256).hexdigest()[:16]
        if hmac.compare_digest(sig, expected):
            return username
    except Exception:
        pass
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({"error": "Invalid field"}), 400

    if not value or len(value) > 100:
        return jsonify({"error": "Invalid query"}), 400

    db = get_db()
    # Using format string for column name (validated above) and
    # string concatenation for the LIKE pattern
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({"error": "Query failed", "detail": str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID. Requires valid session."""
    token = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(token)
    if not caller:
        return jsonify({"error": "Unauthorized"}), 401

    db = get_db()
    user = db.execute("SELECT username, email, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({"error": "Not found"}), 404

@app.route('/api/admin/export', methods=['POST'])
def export_data():
    """Admin endpoint to export user data. Validates role."""
    token = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(token)
    if not caller:
        return jsonify({"error": "Unauthorized"}), 401

    db = get_db()
    user = db.execute("SELECT role FROM users WHERE username = ?", (caller,)).fetchone()
    if not user or user['role'] != 'admin':
        return jsonify({"error": "Forbidden"}), 403

    fmt = request.json.get('format', 'json')
    users = db.execute("SELECT id, username, email, role FROM users").fetchall()
    return jsonify({"users": [dict(u) for u in users], "format": fmt})

if __name__ == '__main__':
    os.makedirs('/app/data', exist_ok=True)
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
